const flatMessageId = clean(input.message_id || "", 80);
const userName = clean(input.user_name || input.telegram_user_name || "", 120);
const errors = [];
const reply = rawMessage && rawMessage.reply_to_message;
const hasReply = rawMessage && Object.prototype.hasOwnProperty.call(rawMessage, "reply_to_message");
const replyId = reply && typeof reply === "object" && !Array.isArray(reply) ? reply.message_id : null;
if (hasReply && (!Number.isSafeInteger(replyId) || replyId <= 0)) {
  errors.push("provider reply message_id is invalid");
}

if (!rawMessage) errors.push("authenticated raw_update.message is required");
if (!text) errors.push("provider message text is required");
if (!telegramUserId) errors.push("provider from.id is required");
if (!telegramChatId) errors.push("provider chat.id is required");
if (chatType !== "private") errors.push("provider private chat is required");
