if (flatText && flatText !== text) errors.push("flat text does not match provider message");
if (flatUserId && flatUserId !== telegramUserId) errors.push("flat user does not match provider sender");
if (flatChatId && flatChatId !== telegramChatId) errors.push("flat chat does not match provider chat");
if (flatMessageId && flatMessageId !== messageId) errors.push("flat message id does not match provider message");

